class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});
  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  bool makhzanOpen = false;
  bool qeyodOpen = false;
  bool asnafOpen = false;
  bool omlatOpen = false;
  bool taqarirOpen = true; // مفتوح مثل صورتك

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(backgroundColor: const Color(0xFF1E5AA8), foregroundColor: Colors.white, title: const Text('محاسب سوفت', style: TextStyle(fontWeight: FontWeight.bold, fontSize:16)), leading: const Icon(Icons.menu), actions: const [Icon(Icons.notifications_none), SizedBox(width:12), Icon(Icons.share), SizedBox(width:10)]),
      body: ListView(children: [
        Container(color: Colors.white, padding: const EdgeInsets.symmetric(vertical:16, horizontal:10), child: Column(children: [Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [_topBtn(context,'قبض/صرف',2), _topBtn(context,'المبيعات',0)]), const SizedBox(height:16), Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [_topBtn(context,'الحسابات',3), _topBtn(context,'المشتريات',1)]),])),
        _sectionBar('عمليات مخزنية', makhzanOpen, ()=>setState(()=>makhzanOpen=!makhzanOpen)),
        if(makhzanOpen) ...[_subItem('صرف مخزني'), _subItem('توريد مخزني'), _subItem('تحويل مخزني'), _subItem('تسوية مخزنية'), _subItem('إضافة مخزن'), _subItem('جرد مخزني')],
        _sectionBar('قيود وحسابات', qeyodOpen, ()=>setState(()=>qeyodOpen=!qeyodOpen)),
        if(qeyodOpen) ...[_subItem('قيد يومي'), _subItem('قيد إفتتاحي'), _subItem('إضافة حساب'), _subItem('حركة الصندوق'), _subItem('دليل الحسابات'), _subItem('إقفال سنوي')],
        _sectionBar('أصناف', asnafOpen, ()=>setState(()=>asnafOpen=!asnafOpen)),
        if(asnafOpen) ...[_subItem('الأصناف'), _subItem('أسعار البيع'), _subItem('وحدات الصنف'), _subItem('فاتورة عرض سعر'), _subItem('طلب شراء')],
        _sectionBar('العملات', omlatOpen, ()=>setState(()=>omlatOpen=!omlatOpen)),
        if(omlatOpen) ...[
          _subItem('إضافة عملة'),
          _subItem('سعر العملات'),
          _subItem('سقف الحساب'),
        ],
        _sectionBar('التقارير', taqarirOpen, ()=>setState(()=>taqarirOpen=!taqarirOpen)),
        if(taqarirOpen) ...[
          _subItem('حركة الأصناف'),
          _subItem('ميزان المراجعة'),
          _subItem('قائمة الدخل'),
          _subItem('المركز المالي'),
          _subItem('تقارير أخرى'),
        ],
      ]),
      bottomNavigationBar: Container(height:55, color: const Color(0xFF1E5AA8), padding: const EdgeInsets.symmetric(horizontal:10), child: const Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Row(children:[Icon(Icons.youtube_searched_for, color:Colors.white), SizedBox(width:6), Text('You\nTube', style:TextStyle(color:Colors.white, fontSize:9))]), Text('المخزن الرئيسي', style: TextStyle(color:Colors.white, fontWeight:FontWeight.bold, fontSize:13)), Icon(Icons.sync, color:Colors.white)])),
    );
  }

  Widget _topBtn(BuildContext c,String t,int type){
    return InkWell(onTap:(){ 
      if(type==0) Navigator.push(c,MaterialPageRoute(builder:(_)=>const SalesListPage()));
      if(type==1) Navigator.push(c,MaterialPageRoute(builder:(_)=>const PurchasesListPage()));
      if(type==2) Navigator.push(c,MaterialPageRoute(builder:(_)=>const QabdSarfPage()));
      if(type==3) Navigator.push(c,MaterialPageRoute(builder:(_)=>const OpeningBalancePage()));
    },child: Column(children:[Stack(children:[Container(width:75,height:65,decoration:BoxDecoration(color:Colors.white, borderRadius:BorderRadius.circular(8), boxShadow:[BoxShadow(color:Colors.grey.shade200, blurRadius:2)]), child: Icon(type==2?Icons.back_hand: type==3?Icons.article_outlined: Icons.shopping_cart, size:36, color: const Color(0xFF1E5AA8))), if(type==0 || type==1) Positioned(top:0,right:0,child: Container(decoration: const BoxDecoration(color:Colors.white, shape:BoxShape.circle), child: const Icon(Icons.add_circle, size:20, color:Color(0xFF1E5AA8))))]), Container(margin:const EdgeInsets.only(top:6), padding:const EdgeInsets.symmetric(horizontal:16, vertical:4), decoration:BoxDecoration(color:const Color(0xFF1E5AA8), borderRadius:BorderRadius.circular(20)), child:Text(t, style:const TextStyle(color:Colors.white, fontSize:11)))]));
  }

  Widget _sectionBar(String t, bool open, VoidCallback onTap){
    return InkWell(onTap: onTap, child: Container(color: const Color(0xFF1E5AA8), padding: const EdgeInsets.symmetric(vertical:10, horizontal:12), margin: const EdgeInsets.only(bottom:1), child: Row(children: [Icon(open?Icons.keyboard_arrow_up:Icons.keyboard_arrow_down, color:Colors.white, size:20), const Spacer(), Text(t, style: const TextStyle(color:Colors.white, fontWeight:FontWeight.bold, fontSize:13))])));}
  
  Widget _subItem(String t){
    return InkWell(
      onTap: ()=>Navigator.push(context, MaterialPageRoute(builder:(_)=>MakhzaniListPage(title: t))),
      child: Container(decoration: const BoxDecoration(color: Colors.white, border: Border(bottom: BorderSide(color: Color(0xFFE8E8E8), width:0.8))), padding: const EdgeInsets.symmetric(vertical:12, horizontal:16), child: Row(children:[const Spacer(), Text(t, style: const TextStyle(fontSize:13, color:Color(0xFF333333)))])),
    );
  }
}

